import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import '../../core/providers/repository_providers.dart'; import '../../core/utils/formatters.dart';
class DuesScreen extends ConsumerWidget{const DuesScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final a=ref.watch(unpaidDuesProvider);return Scaffold(appBar:AppBar(title:const Text('Impayés')),body:a.when(data:(items)=>items.isEmpty?const Center(child:Text('Aucun impayé.')):ListView.builder(padding:const EdgeInsets.all(16),itemCount:items.length,itemBuilder:(_,i){final d=items[i];return Card(child:ListTile(leading:Icon(d.status=='partial'?Icons.timelapse:Icons.warning_amber_rounded),title:Text(d.studentName),subtitle:Text('${d.feeName} • ${d.periodKey}'),trailing:Text(formatXaf(d.balance),style:const TextStyle(fontWeight:FontWeight.w800))));}),loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e'))));}}
